"use strict";
/* Was läuft wo? — client-side room schedule lookup for Uni Wien.
 * Data files (generated by build_data.py):
 *   data/rooms.json         { terms, buildings, rooms: [{d, b, raw: [...]}] }
 *   data/events-<term>.json { fields, rows: [[course_id, group, kind, title,
 *                             room, start, end, src, url], ...] }
 * Everything runs in the browser; events are concrete datetimes, so lookups
 * are plain string comparisons on ISO-ish "YYYY-MM-DDTHH:MM" values.
 */
const $ = (sel) => document.querySelector(sel);

const IDX = { COURSE: 0, GROUP: 1, KIND: 2, TITLE: 3, ROOM: 4, START: 5, END: 6, SRC: 7, URL: 8 };
const MAX_DAY_ROWS = 400;

let roomsData = null;
let view = "list";      // "list" (day) | "week" (7-col grid) | "building" (room × time matrix)
let weekOffset = 0;     // weekly mode: weeks away from the selected date's own week
const termCache = new Map();   // "term" (monolith) or "term|building" (shard) -> rows
const termPromises = new Map(); // same keys -> Promise (dedupe concurrent fetches)

init();

async function init() {
  const saved = localStorage.getItem("rf-theme");
  if (saved) document.documentElement.dataset.theme = saved;
  updateThemeButton();
  $("#themeToggle").addEventListener("click", () => {
    const next = document.documentElement.dataset.theme === "dark" ? "light" : "dark";
    document.documentElement.dataset.theme = next;
    localStorage.setItem("rf-theme", next);
    updateThemeButton();
  });

  const now = new Date();
  $("#date").value = isoDate(now);
  $("#time").value = isoTime(now);

  try {
    const r = await fetch("data/rooms.json");
    if (!r.ok) throw new Error("HTTP " + r.status);
    roomsData = await r.json();
    if (roomsData.generated) $("#dataStamp").textContent = formatGenerated(roomsData.generated);
  } catch (e) {
    setStatus("Raumkatalog konnte nicht geladen werden (data/rooms.json fehlt?) — bitte erst build_data.py ausführen.", true);
    return;
  }
  rebuildBuildingOptions();
  rebuildRoomOptions();
  // Cascading filters: picking a building narrows the rooms, picking a room
  // narrows the buildings. Each change tightens the other dropdown, then re-runs.
  $("#building").addEventListener("change", () => { rebuildRoomOptions(); run(); });
  $("#room").addEventListener("change", () => { rebuildBuildingOptions(); run(); });
  for (const id of ["date", "time"]) {
    document.getElementById(id).addEventListener("change", run);
  }
  $("#go").addEventListener("click", run);
  $("#modeList").addEventListener("click", () => { view = "list"; updateViewUI(); run(); });
  $("#modeWeek").addEventListener("click", () => { view = "week"; updateViewUI(); run(); });
  $("#modeBuilding").addEventListener("click", () => { view = "building"; updateViewUI(); run(); });
  $("#weekPrev").addEventListener("click", () => { weekOffset--; run(); });
  $("#weekNext").addEventListener("click", () => { weekOffset++; run(); });
  run();
}

function updateThemeButton() {
  const dark = document.documentElement.dataset.theme === "dark";
  $("#themeToggle").textContent = dark ? "Hell" : "Dunkel";
}

/* "2026-10-13 19:02" -> "13.10.2026, 19:02 Uhr" (built timestamp from rooms.json) */
function formatGenerated(s) {
  if (!s) return "";
  const d = new Date(s.replace(" ", "T"));
  if (isNaN(d.getTime())) return s;
  return d.toLocaleString("de-AT", { day: "2-digit", month: "2-digit", year: "numeric", hour: "2-digit", minute: "2-digit" }) + " Uhr";
}

/* ---------------------------------------------------- cascading dropdowns */
function rebuildBuildingOptions() {
  const sel = $("#building");
  const roomSel = $("#room").selectedOptions;
  const room = roomSel.length && roomSel[0].value;
  const buildings = new Set();
  for (const r of roomsData.rooms) {
    if (room && r.d !== room) continue;
    buildings.add(r.b);
  }
  setOptions(sel, sortNatural(buildings), "Gebäude");
}

function rebuildRoomOptions() {
  const sel = $("#room");
  const b = $("#building").value;
  const designations = new Set();
  for (const r of roomsData.rooms) {
    if (b && r.b !== b) continue;
    designations.add(r.d);
  }
  setOptions(sel, sortNatural(designations), "Raum");
}

function setOptions(sel, values, label) {
  const prev = sel.value;
  sel.innerHTML = "";
  const all = new Option(`— alle ${label} —`, "");
  sel.add(all);
  for (const v of values) sel.add(new Option(v, v));
  // keep the previous selection if it is still compatible, otherwise reset
  sel.value = [...sel.options].some((o) => o.value === prev) ? prev : "";
}

/* Natural sort so "Hörsaal 2" < "Hörsaal 10". */
function sortNatural(set) {
  const coll = new Intl.Collator("de", { numeric: true, sensitivity: "base" });
  return [...set].sort(coll.compare);
}

/* ------------------------------------------------------------- data load */
function loadTerm(term, building) {
  // Resolve which file serves the selection: a top-building shard, else the
  // combined "rest" shard for any other building, else the full monolith.
  let file = `events-${term}.json`, cacheKey = term;  // "alle" -> monolith
  if (building) {
    const top = roomsData.shards && roomsData.shards[building] && roomsData.shards[building][term];
    if (top) { file = top; cacheKey = `${term}|${building}`; }
    else if (roomsData.shardsRest && roomsData.shardsRest[term]) { file = roomsData.shardsRest[term]; cacheKey = `${term}|rest`; }
  }
  if (termCache.has(cacheKey)) return termCache.get(cacheKey);
  if (!termPromises.has(cacheKey)) {
    termPromises.set(cacheKey,
      fetch(`data/${file}`)
        .then((r) => {
          if (!r.ok) throw new Error(`${file}: HTTP ${r.status}`);
          return r.json();
        })
        .then((data) => {
          termCache.set(cacheKey, data.rows);
          return data.rows;
        })
        .catch((e) => {
          termPromises.delete(cacheKey);
          throw e;
        })
    );
  }
  return termPromises.get(cacheKey);
}

/* ------------------------------------------------------------------ query */
async function run() {
  if (!roomsData) return;
  const building = $("#building").value;
  const room = $("#room").value;
  const date = $("#date").value;
  const time = $("#time").value || "00:00";
  if (!date) return;
  updateViewUI();

  if (view === "building" && !building) {
    setStatus("Gebäudematrix: bitte zuerst ein Gebäude wählen.");
    $("#results").innerHTML = "";
    return;
  }

  // which raw LOCATION strings does the current selection map to?
  const rawSet = new Set();
  for (const r of roomsData.rooms) {
    if (building && r.b !== building) continue;
    if (room && r.d !== room) continue;
    for (const raw of r.raw) rawSet.add(raw);
  }

  setStatus("Lade Belegungsdaten …");
  let loaded;
  try {
    loaded = await Promise.all(roomsData.terms.map((t) => loadTerm(t, building)));
  } catch (e) {
    setStatus("Belegungsdaten konnten nicht geladen werden: " + e.message, true);
    return;
  }
  setStatus(
    `${loaded.reduce((n, rows) => n + rows.length, 0).toLocaleString("de-AT")} ` +
    `Sitzungen aus ${roomsData.terms.length} Semestern geladen.`
  );

  if (view === "week") {
    if (!room) {
      setStatus("Wochenansicht: bitte zuerst einen Raum wählen.");
      $("#results").innerHTML = "";
      return;
    }
    renderWeek(loaded, rawSet, date);
    return;
  }

  if (view === "building") {
    renderBuilding(loaded, building, date);
    return;
  }

  const T = `${date}T${time}`;
  const atTime = [];
  const day = [];
  for (const rows of loaded) {
    for (const row of rows) {
      if (!rawSet.has(row[IDX.ROOM])) continue;
      if (row[IDX.START] <= T && row[IDX.END] > T) atTime.push(row);
      if (row[IDX.START].slice(0, 10) === date) day.push(row);
    }
  }
  atTime.sort((a, b) => a[IDX.START].localeCompare(b[IDX.START]));
  day.sort((a, b) => a[IDX.START].localeCompare(b[IDX.START]) || a[IDX.ROOM].localeCompare(b[IDX.ROOM]));
  render(atTime, day, date, time);
}

function esc(s) {
  return String(s).replace(/[&<>"']/g, (c) =>
    ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}

function hhmm(iso) { return iso.slice(11, 16); }

function badge(row) {
  return row[IDX.SRC] === "exams" ? '<span class="badge">Prüfung</span>' : "";
}

function title(row) {
  const parts = [];
  if (row[IDX.COURSE]) parts.push(`${row[IDX.COURSE]}-${row[IDX.GROUP]}`);
  if (row[IDX.KIND]) parts.push(row[IDX.KIND]);
  if (row[IDX.TITLE]) parts.push(row[IDX.TITLE]);
  return esc(parts.join(" ") || "(Prüfung)");
}

function render(atTime, day, date, time) {
  const out = $("#results");
  const where = describeSelection();
  let html = "";

  html += `<h2>Zur gewählten Zeit (${esc(hhmm(date + "T" + time))}) — ${esc(where)}</h2>`;
  if (atTime.length === 0) {
    html += `<p class="hint">Keine Sitzungen gefunden. Hinweis: außerhalb der Semesterzeiten und am Wochenende ist das oft leer — und Kurse ohne veröffentlichten Termin sind hier nie sichtbar.</p>`;
  } else {
    for (const row of atTime) {
      html += `<div class="hit">
        <div><span class="when">${esc(hhmm(row[IDX.START]))}–${esc(hhmm(row[IDX.END]))}</span>${badge(row)}</div>
        <div>${title(row)}</div>
        <div class="room">${esc(row[IDX.ROOM])}</div>
        ${row[IDX.URL] ? `<a href="${esc(row[IDX.URL])}" target="_blank" rel="noopener">Im u:find öffnen ↗</a>` : ""}
      </div>`;
    }
  }

  html += `<h2>Belegung am ${esc(date)}${day.length > MAX_DAY_ROWS ? ` (erste ${MAX_DAY_ROWS} von ${day.length})` : ""}</h2>`;
  if (day.length === 0) {
    html += `<p class="hint">An diesem Tag ist nichts eingetragen.</p>`;
  } else {
    html += `<table class="day"><thead><tr><th>Zeit</th><th>Raum</th><th>Kurs</th></tr></thead><tbody>`;
    for (const row of day.slice(0, MAX_DAY_ROWS)) {
      html += `<tr>
        <td>${esc(hhmm(row[IDX.START]))}–${esc(hhmm(row[IDX.END]))}</td>
        <td>${esc(row[IDX.ROOM])}${badge(row)}</td>
        <td>${row[IDX.URL] ? `<a href="${esc(row[IDX.URL])}" target="_blank" rel="noopener">${title(row)}</a>` : title(row)}</td>
      </tr>`;
    }
    html += `</tbody></table>`;
  }
  out.innerHTML = html;
}

/* ------------------------------------------------ weekly grid view */
const WD = ["Mo", "Di", "Mi", "Do", "Fr", "Sa", "So"];

function updateViewUI() {
  $("#modeList").classList.toggle("on", view === "list");
  $("#modeWeek").classList.toggle("on", view === "week");
  $("#modeBuilding").classList.toggle("on", view === "building");
  $("#weekNav").hidden = view !== "week";
}

function mondayOf(dateStr) {
  const d = new Date(dateStr + "T00:00:00");
  d.setDate(d.getDate() - ((d.getDay() + 6) % 7)); // roll back to Monday
  return isoDate(d);
}

function addDays(dateStr, n) {
  const d = new Date(dateStr + "T00:00:00");
  d.setDate(d.getDate() + n);
  return isoDate(d);
}

function fmtDay(dateStr) {
  return new Date(dateStr + "T00:00:00")
    .toLocaleDateString("de-AT", { day: "2-digit", month: "2-digit", year: "numeric" });
}

function weekCell(row) {
  return `<div class="wd-slot">
    <span class="t">${esc(hhmm(row[IDX.START]))}–${esc(hhmm(row[IDX.END]))}</span>${badge(row)}<br>
    ${row[IDX.URL] ? `<a href="${esc(row[IDX.URL])}" target="_blank" rel="noopener">${title(row)}</a>` : title(row)}
  </div>`;
}

function renderWeek(loaded, rawSet, date) {
  const monday = addDays(mondayOf(date), weekOffset * 7);
  $("#weekLabel").textContent = `${fmtDay(monday)} – ${fmtDay(addDays(monday, 6))}`;
  const week = {};                       // date string -> rows
  for (let i = 0; i < 7; i++) week[addDays(monday, i)] = [];
  for (const rec of loaded) {
    for (const row of rec) {
      if (!rawSet.has(row[IDX.ROOM])) continue;
      const d = row[IDX.START].slice(0, 10);
      if (d in week) week[d].push(row);
    }
  }
  let html = `<h2>Wochenansicht — ${esc(describeSelection())}</h2>`;
  html += `<div class="week">`;
  for (let i = 0; i < 7; i++) {
    const day = addDays(monday, i);
    const rows = week[day].sort((a, b) => a[IDX.START].localeCompare(b[IDX.START]));
    html += `<div class="weekday">
      <div class="wd-head"><span class="d">${WD[i]}</span>${esc(fmtDay(day))}</div>
      ${rows.length === 0 ? `<span class="hint">—</span>` : rows.map(weekCell).join("")}
    </div>`;
  }
  html += `</div>`;
  $("#results").innerHTML = html;
}

/* ---------------------------------------------- building day matrix */
const PX_PER_MIN = 1;   // 60px per hour on the vertical time axis

function toMin(hhmm) {
  return (+hhmm.slice(0, 2)) * 60 + (+hhmm.slice(3, 5));
}

function hh(m) {
  return String(Math.floor(m / 60)).padStart(2, "0") + ":" + String(m % 60).padStart(2, "0");
}

function renderBuilding(loaded, building, date) {
  // rooms of this building, natural-sorted
  const roomCols = sortNatural(new Set(roomsData.rooms.filter((r) => r.b === building).map((r) => r.d)));

  // raw LOCATION string -> designations within this building
  const rawToD = new Map();
  for (const r of roomsData.rooms) {
    if (r.b !== building) continue;
    for (const raw of r.raw) {
      let a = rawToD.get(raw);
      if (!a) rawToD.set(raw, (a = []));
      if (!a.includes(r.d)) a.push(r.d);
    }
  }

  // bucket events into per-room columns and find the day's time range
  const cols = {};
  let mn = Infinity, mx = -Infinity, count = 0;
  for (const rec of loaded) {
    for (const row of rec) {
      if (row[IDX.START].slice(0, 10) !== date) continue;
      const ds = rawToD.get(row[IDX.ROOM]);
      if (!ds) continue;
      const s = toMin(row[IDX.START].slice(11, 16));
      const e = toMin(row[IDX.END].slice(11, 16));
      if (e <= s) continue;             // skip zero-length / full-day markers
      mn = Math.min(mn, s); mx = Math.max(mx, e);
      for (const d of ds) { (cols[d] = cols[d] || []).push(row); count++; }
    }
  }

  if (!isFinite(mn) || !isFinite(mx)) { mn = 8 * 60; mx = 20 * 60; }
  const dayStart = Math.floor(mn / 60) * 60;
  const dayEnd = Math.ceil(mx / 60) * 60;
  const totalMin = Math.max(dayEnd - dayStart, 60);
  const totalPx = totalMin * PX_PER_MIN;

  // hour labels
  let labels = "";
  for (let m = dayStart; m <= dayEnd; m += 60) {
    labels += `<div class="hh" style="top:${(m - dayStart) * PX_PER_MIN}px">${hh(m)}</div>`;
  }

  function cell(rows) {
    let html = "";
    for (const row of rows.slice().sort((a, b) => a[IDX.START].localeCompare(b[IDX.START]))) {
      const s = toMin(row[IDX.START].slice(11, 16));
      const e = toMin(row[IDX.END].slice(11, 16));
      const top = (s - dayStart) * PX_PER_MIN;
      const height = Math.max((e - s) * PX_PER_MIN - 2, 18);
      const exam = row[IDX.SRC] === "exams";
      const name = title(row);
      const link = row[IDX.URL] ? `<a href="${esc(row[IDX.URL])}" target="_blank" rel="noopener">${name}</a>` : name;
      html += `<div class="booking${exam ? " exam" : ""}" style="top:${top}px;height:${height}px">` +
        `<div class="b-time">${esc(hhmm(row[IDX.START]))}–${esc(hhmm(row[IDX.END]))}</div>` +
        `<div class="b-title">${link}</div>` +
        `</div>`;
    }
    return html;
  }

  let html = `<h2>Gebäude — ${esc(describeSelection())} · ${esc(date)}</h2>`;
  html += `<div class="matrix-scroll">`;
  html += `<div class="matrix-time"><div class="time-head"></div><div class="time-body" style="height:${totalPx}px">${labels}</div></div>`;
  html += `<div class="matrix-grid">`;
  for (const d of roomCols) {
    html += `<div class="room-col"><div class="room-head">${esc(d)}</div><div class="room-body" style="height:${totalPx}px">${cell(cols[d] || [])}</div></div>`;
  }
  html += `</div>`;
  html += `</div>`;
  $("#results").innerHTML = html;
  setStatus(`${count} Sitzungen am ${date} in ${building} (${roomCols.length} Räume).`);
}

function describeSelection() {
  const b = $("#building").value, r = $("#room").value;
  if (b && r) return `${r} · ${b}`;
  if (b) return `alle Räume in ${b}`;
  if (r) return `${r} (alle Gebäude)`;
  return "alle Räume";
}

function setStatus(msg, isError) {
  const el = $("#status");
  el.textContent = msg;
  el.classList.toggle("error", !!isError);
}

function isoDate(d) {
  return d.getFullYear().toString().padStart(4, "0") + "-" +
    String(d.getMonth() + 1).padStart(2, "0") + "-" + String(d.getDate()).padStart(2, "0");
}
function isoTime(d) {
  return String(d.getHours()).padStart(2, "0") + ":" + String(d.getMinutes()).padStart(2, "0");
}
